const updates = $json.result || [];
const items = [];

function getAllowedIds() {
  let raw = '';
  try {
    raw = $env.TELEGRAM_ALLOWED_USER_IDS || '';
  } catch (error) {
    raw = '';
  }
  return String(raw)
    .split(',')
    .map((id) => id.trim())
    .filter(Boolean);
}

const allowedIds = getAllowedIds();

for (const update of updates) {
  const message = update.message;
  if (!message || typeof message.text !== 'string') continue;

  const userId = message.from?.id;
  const isAllowed = allowedIds.length === 0 || allowedIds.includes(String(userId));

  items.push({
    json: {
      telegram_update_id: update.update_id,
      user_id: userId,
      chat_id: message.chat?.id,
      message_id: message.message_id,
      user_message: message.text,
      message_kind: 'text',
      received_at: message.date ? new Date(message.date * 1000).toISOString() : new Date().toISOString(),
      is_allowed: isAllowed
    }
  });
}

return items;

const updates = $json.result || [];
const items = [];

function getAllowedIds() {
  let raw = '';
  try {
    raw = $env.TELEGRAM_ALLOWED_USER_IDS || '';
  } catch (error) {
    raw = '';
  }
  return String(raw)
    .split(',')
    .map((id) => id.trim())
    .filter(Boolean);
}

const allowedIds = getAllowedIds();

for (const update of updates) {
  const message = update.message;
  if (!message || !message.voice?.file_id) continue;

  const userId = message.from?.id;
  const isAllowed = allowedIds.length === 0 || allowedIds.includes(String(userId));

  items.push({
    json: {
      telegram_update_id: update.update_id,
      user_id: userId,
      chat_id: message.chat?.id,
      message_id: message.message_id,
      voice_file_id: message.voice.file_id,
      voice_duration: message.voice.duration,
      message_kind: 'voice',
      received_at: message.date ? new Date(message.date * 1000).toISOString() : new Date().toISOString(),
      is_allowed: isAllowed
    }
  });
}

return items;

return items.map((item) => {
  if (item.binary?.data) {
    item.binary.data.fileName = 'telegram-voice.ogg';
    item.binary.data.fileExtension = 'ogg';
    item.binary.data.mimeType = 'audio/ogg';
  }
  return item;
});

const bases = $items("Normalize Voice Updates").map((item) => item.json);
return items.map((item, index) => {
  const base = bases[index] || {};
  const text = String(item.json.text || '').trim();
  const error = item.json.error || item.json.message || null;
  return {
    json: {
      ...base,
      user_message: text || '[voice transcription failed] Please repeat the voice message or send text.',
      transcription_error: text ? null : (error ? JSON.stringify(error) : 'empty_transcription'),
    },
  };
});

return items
  .filter(item => item.json.is_allowed !== false)
  .map(item => ({ json: item.json }));

const mem = $items("Load Memory");
const base = (mem && mem[0] && mem[0].json) ? mem[0].json : {};
const choice = $json.choices && $json.choices[0];
const raw = (choice && choice.message && choice.message.content) ? choice.message.content : "{}";
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  parsed = { route: "chat", confidence: 0, extracted_data: {}, parse_error: raw };
}
if (!["finance_add", "finance_report", "search", "reminder_add", "chat"].includes(parsed.route)) {
  parsed.route = "chat";
}
return [{ json: { ...base, route: parsed.route, confidence: parsed.confidence || 0, extracted_data: parsed.extracted_data || {} } }];

let base = {};
try {
  const g = $items("Gate Search");
  if (g && g[0] && g[0].json) {
    base = g[0].json;
  }
} catch (error) {
  base = {};
}
return [{ json: { ...base, tool_data: { type: "search", results: $json.results || [], answer: $json.answer || null } } }];

function branchItems(nodeName) {
  try {
    const rows = $items(nodeName);
    return Array.isArray(rows) ? rows : [];
  } catch (error) {
    return [];
  }
}
const candidates = [
  ...branchItems("Tool Data Chat").map((i) => i.json),
  ...branchItems("Tool Data Search").map((i) => i.json),
  ...branchItems("Finance Add SQL").map((i) => i.json),
  ...branchItems("Finance Report SQL").map((i) => i.json),
  ...branchItems("Reminder Add SQL").map((i) => i.json),
];
const base = candidates.find(Boolean) || {};
const choice = $json.choices && $json.choices[0];
const assistant_reply = (choice && choice.message && choice.message.content) ? choice.message.content : "OK.";
return [{ json: { ...base, assistant_reply } }];
